/*
 * A045211  Numbers whose base-5 representation contains exactly two 0's and
 *          one 4.
 * https://oeis.org/A045211
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 45, u32 n <= 45, u64 n <= 45, u128 n <= 45,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by brute–force search: iterate over integers,
   select those whose base–5 representation contains exactly
   two 0's and one 4.  a(1) is the first such integer. */

/* Note: the implementation uses only the operations allowed
   for seq_t and idx_t (arithmetic, comparison, ++, --). */

seq_t a(idx_t n)
{
    seq_t term = 0;          /* value of the n‑th term */
    idx_t found = 0;         /* number of terms found so far */
    seq_t x = 1;             /* current candidate integer */

    while (found < n) {
        seq_t t = x;
        int zeros = 0, fours = 0;

        /* Count digits of x in base 5 */
        while (t > 0) {
            int d = (int)(t % 5);
            t /= 5;
            if (d == 0)   zeros++;
            else if (d == 4) fours++;
        }

        if (zeros == 2 && fours == 1) {
            term = x;
            found++;
        }
        x++;        /* next candidate */
    }

    return term;
}
